242:   function updateFog(frame) {
243:     visibleCells.fill(0);
244:     const scouts = [...frame.units, ...frame.buildings].filter(e => e.team === 'blue');
245:     for (const source of scouts) {
246:       const radius = source.kind === 'hq' ? .13 : source.kind === 'scout' ? .14 : source.kind === 'tank' ? .12 : source.kind === 'infantry' ? .105 : source.kind === 'collector' ? .11 : .085;
247:       const cx = source.x * 128, cy = source.y * 128, rx = Math.ceil(radius * 128 / aspect), ry = Math.ceil(radius * 128);
248:       for (let y = Math.max(0, Math.floor(cy - ry)); y < Math.min(128, Math.ceil(cy + ry)); y++) {
249:         for (let x = Math.max(0, Math.floor(cx - rx)); x < Math.min(128, Math.ceil(cx + rx)); x++) {
250:           if (Math.hypot(((x + .5) / 128 - source.x) * aspect, (y + .5) / 128 - source.y) <= radius) {
251:             const i = y * 128 + x; visibleCells[i] = 1; discovered[i] = 1;
252:           }
253:         }
254:       }
255:     }
256:     let changed = false;
257:     for (let i = 0; i < discovered.length; i++) {
258:       const alpha = visibleCells[i] ? 0 : discovered[i] ? 168 : 248;
259:       const p = i * 4;
260:       if (fogPixels.data[p] !== 0 || fogPixels.data[p + 1] !== 0 || fogPixels.data[p + 2] !== 0 || fogPixels.data[p + 3] !== alpha) {
261:         fogPixels.data[p] = fogPixels.data[p + 1] = fogPixels.data[p + 2] = 0;
262:         fogPixels.data[p + 3] = alpha; changed = true;
263:       }
264:     }
265:     if (changed) { fogContext.putImageData(fogPixels, 0, 0); fogTexture.needsUpdate = true; }
266:   }
