268:   function render(frame) {
269:     currentZoom = frame.camera.z;
270:     resize();
271:     const centerX = (frame.camera.x - .5) * WORLD * aspect;
272:     const centerZ = (frame.camera.y - .5) * WORLD;
273:     camera.position.set(centerX, 190, centerZ + 92);
274:     camera.lookAt(centerX, 0, centerZ);
275:     camera.rotation.z = 0;
276:     camera.left = -HALF_WORLD * aspect / currentZoom; camera.right = HALF_WORLD * aspect / currentZoom;
277:     camera.top = HALF_WORLD / currentZoom; camera.bottom = -HALF_WORLD / currentZoom; camera.updateProjectionMatrix();
278: 
279:     const live = new Set();
280:     updateFog(frame);
281:     for (const entity of [...frame.buildings, ...frame.units, ...frame.enemies]) {
282:       live.add(entity.id);
283:       let obj = entities.get(entity.id);
284:       if (!obj || obj.userData.kind !== entity.kind || obj.userData.faction !== frame.faction) {
285:         if (obj) { entityRoot.remove(obj); disposeTree(obj); }
286:         obj = buildEntity(entity, frame.faction); entities.set(entity.id, obj); entityRoot.add(obj);
287:       }
288:       const scale = entity.size ? Math.max(.35, entity.size / 70) : Math.max(.85, entity.radius / 7);
289:       position(obj, entity.x, entity.y);
290:       obj.scale.setScalar(scale);
291:       obj.rotation.y = Math.atan2(frame.camera.x - entity.x, frame.camera.y - entity.y);
292:       const fogIndex = Math.max(0, Math.min(127, Math.floor(entity.y * 128))) * 128 + Math.max(0, Math.min(127, Math.floor(entity.x * 128)));
293:       obj.visible = entity.hp > 0 && (entity.team === 'blue' || visibleCells[fogIndex] === 1);
294:       obj.userData.selection.visible = entity === frame.selected;
295:       obj.userData.selection.scale.setScalar(entity.size ? 1 : .6);
296:       obj.userData.selection.material.opacity = entity.team === 'blue' ? .9 : .65;
297:       obj.userData.model.rotation.y = entity.target ? Math.atan2(entity.target.x - entity.x, entity.target.y - entity.y) - obj.rotation.y : 0;
298:       obj.userData.health.visible = entity.hp < entity.max;
299:       const ratio = Math.max(0, Math.min(1, entity.hp / entity.max));
300:       obj.userData.healthFill.scale.x = ratio;
301:       obj.userData.healthFill.position.x = -(obj.userData.health.userData.width * (1 - ratio)) / 2;
302:       const hopper = obj.getObjectByName('ore hopper');
303:       if (hopper) hopper.material = entity.carry > 0 ? mat('#b6944d') : mat('#756a49');
304:       const vehicle = obj.userData.model.getObjectByName('vehicle');
305:       if (vehicle) vehicle.position.y = entity.kind === 'collector' && entity.harvesting ? Math.sin(frame.time * 2.5) * .08 : 0;
306:     }
307:     for (const [id, obj] of entities) if (!live.has(id)) { entityRoot.remove(obj); disposeTree(obj); entities.delete(id); }
308:     syncResources(frame);
309:     syncEffects(frame);
