312:       if (!ghost) {
313:         ghost = new THREE.Mesh(new THREE.BoxGeometry(8, 4, 8), new THREE.MeshBasicMaterial({ color: '#c8f05b', wireframe: true, transparent: true, opacity: .8 }));
