352:   function syncEffects(frame) {
353:     const key = `${frame.shots.length}:${frame.particles.length}:${Math.floor(frame.time * 10)}`;
354:     if (transientKey === key) return;
355:     transientKey = key;
356:     while (transientRoot.children.length) {
357:       const child = transientRoot.children[0]; transientRoot.remove(child); disposeTree(child);
358:     }
359:     for (const shot of frame.shots) {
360:       if (!shot.target) continue;
361:       const t = 1 - shot.life / shot.max;
362:       const a = new THREE.Vector3((shot.x - .5) * WORLD * aspect, .72, (shot.y - .5) * WORLD);
363:       const b = new THREE.Vector3((shot.x + (shot.target.x - shot.x) * t - .5) * WORLD * aspect, .72, (shot.y + (shot.target.y - shot.y) * t - .5) * WORLD);
364:       const beam = new THREE.Mesh(new THREE.CylinderGeometry(.075, .075, a.distanceTo(b), 5), basic(shot.color));
365:       beam.position.copy(a).add(b).multiplyScalar(.5); beam.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), b.sub(a).normalize()); transientRoot.add(beam);
366:     }
367:     for (const particle of frame.particles) {
368:       const mesh = new THREE.Mesh(new THREE.SphereGeometry(.35 + (1 - particle.life / particle.max) * 1.7, 8, 6), basic(particle.color, Math.max(.12, particle.life / particle.max)));
