302:   function updateFog(frame) {
303:     visibleCells.fill(0);
304:     const scouts = [...frame.units, ...frame.buildings].filter(e => e.team === 'blue');
305:     for (const source of scouts) {
306:       const radius = source.kind === 'hq' ? .13 : source.kind === 'scout' ? .14 : source.kind === 'tank' ? .12 : source.kind === 'infantry' ? .105 : source.kind === 'collector' ? .11 : .085;
307:       const cx = source.x * 128, cy = source.y * 128, rx = Math.ceil(radius * 128 / aspect), ry = Math.ceil(radius * 128);
308:       for (let y = Math.max(0, Math.floor(cy - ry)); y < Math.min(128, Math.ceil(cy + ry)); y++) {
309:         for (let x = Math.max(0, Math.floor(cx - rx)); x < Math.min(128, Math.ceil(cx + rx)); x++) {
310:           if (Math.hypot(((x + .5) / 128 - source.x) * aspect, (y + .5) / 128 - source.y) <= radius) {
311:             const i = y * 128 + x; visibleCells[i] = 1; discovered[i] = 1;
312:           }
313:         }
314:       }
315:     }
316:     let changed = false;
317:     for (let i = 0; i < discovered.length; i++) {
318:       const alpha = discovered[i] ? 0 : 248;
319:       const p = i * 4;
320:       if (fogPixels.data[p] !== 0 || fogPixels.data[p + 1] !== 0 || fogPixels.data[p + 2] !== 0 || fogPixels.data[p + 3] !== alpha) {
321:         fogPixels.data[p] = fogPixels.data[p + 1] = fogPixels.data[p + 2] = 0;
322:         fogPixels.data[p + 3] = alpha; changed = true;
